def family_init(ctx):
    import math
    bars = ctx.bars
    n = len(bars)
    c = [float(b["c"]) for b in bars]
    day = [str(b["t"])[:10] for b in bars]

    # ---- h-bar log returns, never across the overnight gap ----
    h = max(1, int(ctx.p.h_bars))
    ret = [None] * n
    for i in range(h, n):
        if day[i] == day[i - h] and c[i - h] > 0:
            ret[i] = math.log(c[i] / c[i - h])

    # non-overlapping return stream, in bar order, with its bar index
    stream = []
    last_used = -10 ** 9
    for i in range(n):
        if ret[i] is not None and i - last_used >= h:
            stream.append((i, ret[i]))
            last_used = i

    # ---- rho, fixed once per session from everything before that session ----
    lb = int(ctx.p.rho_lb)
    rho = [None] * n
    cur = None
    k = 0                       # how much of `stream` predates this session
    for i in range(n):
        if i == 0 or day[i] != day[i - 1]:
            while k < len(stream) and stream[k][0] < i:
                k += 1
            w = [x[1] for x in stream[max(0, k - lb):k]]
            cur = None
            if len(w) >= 30:
                m = sum(w) / len(w)
                num = sum((w[j] - m) * (w[j - 1] - m) for j in range(1, len(w)))
                den = sum((x - m) ** 2 for x in w)
                if den > 0:
                    cur = num / den
        rho[i] = cur
    ctx.rho = ctx.series(rho, "rho")
    ctx.d = ctx.indicator("donchian", period=int(ctx.p.brk))


def signal(ctx, i):
    r = ctx.rho[i]
    if r is None:
        return 0
    thr = ctx.p.rho_thr

    if r > thr:
        # SHORT-GAMMA: dealers amplify, so a break of the prior extreme runs
        u, l = ctx.d.upper[i - 1], ctx.d.lower[i - 1]
        if u is None or l is None:
            return 0
        if ctx.c[i] > u:
            return 1
        if ctx.c[i] < l:
            return -1
        return 0

    if r < -thr:
        # LONG-GAMMA: dealers dampen, so the break gets sold back -- require
        # the previous bar to have broken and THIS bar to reclaim the level
        u2, l2 = ctx.d.upper[i - 2], ctx.d.lower[i - 2]
        if u2 is None or l2 is None:
            return 0
        if ctx.c[i - 1] < l2 and ctx.c[i] > l2:
            return 1
        if ctx.c[i - 1] > u2 and ctx.c[i] < u2:
            return -1
    return 0
